INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (155, 2, 100101, 8, 44, "獣人族", 16, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "トゥインクルウィッシュ", "ヒヨリ", "A", 0, "人助けが大好き！　前向き格闘娘", 27, "人助け、応援", "東山奈央");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (158, 2, 100201, 4, 47, "ヒューマン", 17, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "トゥインクルウィッシュ", "ユイ", "O", 0, "戦闘のサポートが得意な、心優しい少女", 5, "料理、人間観察", "種田梨沙");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (163, 2, 100301, 1, 46, "魔族", 18, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "トゥインクルウィッシュ", "レイ", "B", 0, "クールで何事にも真っ直ぐな剣士", 12, "読書、乗馬、お茶", "早見沙織");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (128, 5, 100401, 8, 27, "ヒューマン", 9, "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", "リトルリリカル", "ミソギ", "O", 0, "探検好きのイタズラっ子", 10, "いたずら、探検", "諸星すみれ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (146, 8, 100501, 11, 40, "獣人族", 12, "？？？", "王宮騎士団（NIGHTMARE）", "マツリ", "O", 0, "ヒーローに憧れる騎士見習いの少女", 25, "ヒーローごっこ", "下田麻美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (150, 7, 100601, 11, 42, "魔族", 13, "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "悪魔偽王国軍（ディアボロス）", "アカリ", "O", 0, "甘え上手なみんなの人気者", 22, "サックス", "浅倉杏美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (130, 7, 100701, 1, 32, "魔族", 14, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "悪魔偽王国軍（ディアボロス）", "ミヤコ", "B", 0, "プリン大好きゴースト娘", 23, "プリンを食べること", "雨宮天");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (150, 15, 100801, 10, 40, "エルフ", 14, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "ヴァイスフリューゲル　ランドソル支部", "ユキ", "AB", 0, "ボクは誰よりも美しい", 10, "鏡で自分を見ること", "大空直美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (159, 13, 100901, 7, 45, "魔族", 17, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "トワイライトキャラバン", "アンナ", "A", 0, "前世を信じる中二病患者、「疾風の冥姫」", 5, "小説執筆", "髙野麻美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (155, 10, 101001, 9, 42, "獣人族", 16, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "自警団（カォン）", "マホ", "O", 0, "マホマホ王国のプリンセス", 22, "空想、ぬいぐるみ集め", "内田真礼");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, 3, 101101, 8, 44, "ヒューマン", 15, "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "ラビリンス", "リノ", "A", 0, "人懐っこくてマシンガントークな妹系少女", 25, "お裁縫", "阿澄佳奈");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, 6, 101201, 12, 46, "エルフ", 17, "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", "フォレスティエ", "ハツネ", "A", 0, "みんなのために超能力を使う眠り姫", 24, "妹と遊ぶこと、二度寝、昼寝、早寝", "大橋彩香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (166, 13, 101301, 8, 55, "魔族", 18, "", "トワイライトキャラバン", "ナナカ", "O", 0, "オタク全開な魔法少女", 21, "読書、魔法", "佳村はるか");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (152, 10, 101401, 11, 41, "獣人族", 15, "test", "自警団（カォン）", "カスミ", "AB", 0, "頭脳明晰な美少女名探偵", 3, "読書、推理", "水瀬いのり");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (165, 6, 101501, 9, 54, "エルフ", 21, "test", "フォレスティエ", "ミサト", "O", 0, "母性溢れる優しいみんなの「ミサト先生」", 5, "絵本作り", "國府田マリ子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (167, 14, 101601, 4, 48, "魔族", 17, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "ルーセント学院", "スズナ", "O", 0, "天真爛漫で人気者のカリスマモデル", 10, "ファッション", "上坂すみれ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (158, 10, 101701, 7, 53, "獣人族", 17, "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "自警団（カォン）", "カオリ", "A", 0, "いつでも「なんくるないさ～」な天然娘", 7, "踊り、空手", "高森奈津美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (162, 14, 101801, 8, 52, "魔族", 23, "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "ルーセント学院", "イオ", "B", 0, "多くの男性を魅了する無垢な女教師", 14, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", "伊藤静");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (117, 5, 102001, 4, 21, "獣人族", 10, "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", "リトルリリカル", "ミミ", "O", 0, "お歌もにんじんも、ウサギさんも大好き♪", 3, "かわいいもの集め", "日高里菜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (150, 9, 102101, 6, 40, "ヒューマン", 12, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "サレンディア救護院", "クルミ", "B", 0, "泣き虫で臆病な守ってあげたい女の子", 9, "観劇、おままごと", "植田佳奈");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (150, 7, 102201, 11, 40, "魔族", 13, "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", "悪魔偽王国軍（ディアボロス）", "ヨリ", "O", 0, "人見知りであまのじゃくな女の子", 22, "ゲーム全般", "原紗友里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (148, 9, 102301, 5, 38, "ヒューマン", 14, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "サレンディア救護院", "アヤネ", "B", 0, "ぷうきちといつも一緒！", 10, "屋内でできる遊び", "芹澤優");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (154, 9, 102501, 12, 43, "ヒューマン", 15, "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "サレンディア救護院", "スズメ", "O", 0, "お嬢さまのためにがんばるドジっ娘メイド", 12, "ご奉仕", "悠木碧");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (144, 11, 102601, 1, 42, "獣人族", 17, "test", "牧場（エリザベスパーク）", "リン", "B", 0, "遊びと睡眠が何より大事なぐうたら娘", 1, "あんパン", "小岩井ことり");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (154, 13, 102701, 7, 43, "魔族", 16, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "トワイライトキャラバン", "エリコ", "B", 0, "運命の相手に一途すぎる乙女", 30, "実験、裁縫、料理", "橋本ちなみ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, 9, 102801, 10, 43, "エルフ", 17, "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "サレンディア救護院", "サレン", "A", 0, "救護院を経営する優しい庶民派お嬢様", 4, "経営、お茶会", "堀江由衣");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (157, 4, 102901, 1, 40, "ヒューマン", 17, "いつか世界中の人達をファンにしてみせる！\nトップアイドルになるその日まで、\n応援よろしくね♪", "カルミナ", "ノゾミ", "B", 0, "歌って踊れる大人気アイドル", 24, "舞台鑑賞、ダンス", "日笠陽子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (163, 15, 103001, 8, 51, "ヒューマン", 16, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "ヴァイスフリューゲル　ランドソル支部", "ニノン", "O", 0, "トーゴクの神秘、オシエテクダサイ！", 31, "忍法開発", "佐藤聡美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (157, 7, 103101, 12, 42, "魔族", 18, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "悪魔偽王国軍（ディアボロス）", "シノブ", "AB", 0, "占いが得意な霊能少女", 22, "占い", "大坪由佳");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (157, 12, 103201, 3, 45, "ヒューマン", 18, "この私とともにいる限り、\nお金に不自由はさせませんわ！", "メルクリウス財団", "アキノ", "AB", 0, "一人前の商人を目指すパワフルお嬢様", 12, "慈善事業", "松嵜麗");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (142, 11, 103301, 3, 35, "ヒューマン", 20, "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", "牧場（エリザベスパーク）", "マヒル", "B", 0, "みんなを笑顔にするお笑い牧場主", 3, "漫才", "新田恵海");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (164, 12, 103401, 3, 55, "エルフ", 22, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "メルクリウス財団", "ユカリ", "A", 0, "純情でほっとけない大人の女性", 16, "ウインドーショッピング", "今井麻美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (118, 5, 103601, 2, 21, "エルフ", 8, "test", "リトルリリカル", "キョウカ", "A", 0, "礼儀正しくしっかり者のちびっ子優等生", 2, "お勉強", "小倉唯");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (149, 8, 103701, 8, 43, "ヒューマン", 13, "test", "王宮騎士団（NIGHTMARE）", "トモ", "A", 0, "義理堅くてからかい好きな剣術少女", 11, "剣術、年長者をからかう", "茅原実里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (153, 11, 103801, 11, 40, "獣人族", 14, "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", "牧場（エリザベスパーク）", "シオリ", "A", 0, "読書が趣味の病弱少女", 3, "読書、お散歩", "小清水亜美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (158, 6, 104001, 6, 44, "エルフ", 13, "友達ができるその日まで…\nBB団で\nトレーニングですっ！", "フォレスティエ", "アオイ", "AB", 0, "「友達」に憧れる、エルフの森の女の子", 6, "友達作りのイメトレ", "花澤香菜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (163, 4, 104201, 6, 46, "ヒューマン", 17, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "カルミナ", "チカ", "O", 0, "人々を守るために歌う、唱喚士の少女", 3, "各種楽器", "福原綾香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (168, 10, 104301, 8, 54, "獣人族", 17, "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", "自警団（カォン）", "マコト", "O", 0, "男勝りで情に厚いワイルド娘", 9, "お菓子作り", "小松未可子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (172, 7, 104401, 5, 50, "魔族", "??", "test", "悪魔偽王国軍（ディアボロス）", "イリヤ", "A", 0, "かつては夜を支配した最強の吸血鬼", 5, "世界征服", "丹下桜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (157, 15, 104501, 11, 49, "ヒューマン", 18, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "ヴァイスフリューゲル　ランドソル支部", "クウカ", "AB", 0, "妄想大好き！　ほんとは照れ屋な女の子", 19, "小説を読むこと", "長妻樹里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (158, 12, 104601, 3, 48, "獣人族", 19, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "メルクリウス財団", "タマキ", "AB", 0, "弱きを助け強きをくじく猫娘", 1, "猫とたわむれること", "沼倉愛美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (171, 8, 104701, 10, 50, "ヒューマン", 25, "？？？", "王宮騎士団（NIGHTMARE）", "ジュン", "A", 0, "素顔を見せない冷静沈着な女性騎士", 25, "格闘技、湯浴み", "川澄綾子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (163, 12, 104801, 11, 49, "ヒューマン", 20, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "メルクリウス財団", "ミフユ", "O", 0, "仕事も私事も効率優先な傭兵少女", 11, "傭兵などのアルバイト", "田所あずさ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (168, 3, 104901, 10, 54, "ヒューマン", 18, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "ラビリンス", "シズル", "O", 0, "お姉ちゃんがお世話してあげるからねっ！", 24, "家事全般", "生天目仁美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (120, 14, 105001, 1, 22, "魔族", 11, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "ルーセント学院", "ミサキ", "A", 0, "ちょっとおませな恋に恋する女の子", 3, "ファッション誌鑑賞、コスメ集め", "久野美咲");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (166, 13, 105101, 3, 53, "ヒューマン", 27, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "トワイライトキャラバン", "ミツキ", "A", 0, "実験が趣味の危険な科学者", 7, "研究、実験", "三石琴乃");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (150, 11, 105201, 3, 100, "獣人族", 17, "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", "牧場（エリザベスパーク）", "リマ", "A", 0, "乙女チックなもふもふアニマル", 14, "毛繕い、お喋り", "徳井青空");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (140, 15, 105301, 7, 33, "ヒューマン", 17, "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "ヴァイスフリューゲル　ランドソル支部", "モニカ", "A", 0, "見た目も中身もお子ちゃまな異国の軍人", 28, "お菓子屋通い", "辻あゆみ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (153, 4, 105401, 9, 45, "ヒューマン", 14, "test", "カルミナ", "ツムギ", "AB", 0, "ファッション大好きなキュートガール", 7, "裁縫", "木戸衣吹");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (155, 15, 105501, 4, 43, "エルフ", 16, "test", "ヴァイスフリューゲル　ランドソル支部", "アユミ", "O", 0, "どこまでも一途に慕う、純情乙女", 7, "観察", "大関英里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (167, 13, 105601, 7, 54, "ヒューマン", 25, "test", "トワイライトキャラバン", "ルカ", "B", 0, "人情味溢れる粋でいなせな「姉御」", 11, "釣り", "佐藤利奈");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, "", 105701, 3, 45, "ヒューマン", 17, "私ね、一人前の騎空士になりたいんだ\nいつか父さんみたいな騎空士になって、\n空の果てまで旅する。それが私の夢だよ！", "？？？", "ジータ", "O", 0, "空への冒険を夢見る騎空士の少女", 10, "冒険、おしゃべり", "金元寿子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, 1, 105801, 3, 46, "ヒューマン", 17, "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "美食殿", "ペコリーヌ", "O", 0, "いつも元気な腹ペコ少女", 31, "食べ歩き、料理", "M・A・O");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (140, 1, 105901, 5, 35, "エルフ", 11, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "美食殿", "コッコロ", "B", 0, "主を慕う、小さなガイド役", 11, "瞑想、動植物の飼育", "伊藤美来");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (152, 1, 106001, 9, 39, "獣人族", 14, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "美食殿", "キャル", "A", 0, "行き倒れの謎のネコミミ魔法使い", 2, "猫と遊ぶ", "立花理香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (148, "", 106101, 8, 40, "ヒューマン", 16, "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", "？？？", "ムイミ", "O", 0, "さまよえる謎の少女", 11, "冒険、思い出話", "潘めぐみ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (155, "", 106301, 6, 42, "エルフ", 15, "", "？？？", "アリサ", "O", 0, "森番を目指すエルフの少女", 17, "キレイな葉っぱを集めること", "優木かな");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (147, 1, 106401, 12, "???", "ドラゴン族", 14, "", "美食殿", "シェフィ", "B", 0, "記憶喪失のドラゴン娘", 14, "読書、ストレッチ", "近藤玲奈");
