INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (145, 17, 106601, 9, "???", "ドラゴン族", 13, "", "ドラゴンズネスト", "イノリ", "AB", 0, "口が達者なヘタレドラゴン", 29, "ゲーム", "藤田茜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (168, 17, 106701, 4, "???", "ドラゴン族", 25, "", "ドラゴンズネスト", "ホマレ", "O", 0, "妖しい微笑で全てを見透かす臥竜の頭領", 17, "絵画、読書", "大西沙織");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (160, 3, 106801, 7, "??", "ヒューマン", 25, "", "ラビリンス", "ラビリスタ", "AB", 0, "秘密結社ラビリンスの『迷宮女王』", 25, "人間観察", "沢城みゆき");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (166, "", 106901, 7, "??", "獣人族", 29, "", "？？？", "カイザーインサイト", "AB", 0, "謎に包まれたランドソルの主", 1, "占い、支配", "蒼井翔太");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (149, "", 107001, 3, "??", "エルフ", 24, "", "？？？", "ネネカ", "O", 0, "研究所に隠れ住む物静かなお姉さん", 24, "物真似、芸術鑑賞", "井口裕香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (165, 8, 107101, 2, "??", "ヒューマン", 27, "", "王宮騎士団（NIGHTMARE）", "クリスティーナ", "O", 0, "傍若無人な王宮騎士団副団長", 7, "強敵との闘争", "たかはし智秋");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, 1, 107501, 3, 46, "ヒューマン", 17, "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "美食殿", "ペコリーヌ（サマー）", "O", 0, "いつも元気な腹ペコ少女", 31, "食べ歩き、料理", "M・A・O");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (140, 1, 107601, 5, 35, "エルフ", 11, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "美食殿", "コッコロ（サマー）", "B", 0, "主を慕う、小さなガイド役", 11, "瞑想、動植物の飼育", "伊藤美来");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (154, 9, 107701, 12, 43, "ヒューマン", 15, "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "サレンディア救護院", "スズメ（サマー）", "O", 0, "お嬢さまのためにがんばるドジっ娘メイド", 12, "ご奉仕", "悠木碧");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (152, 1, 107801, 9, 39, "獣人族", 14, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "美食殿", "キャル（サマー）", "A", 0, "行き倒れの謎のネコミミ魔法使い", 2, "猫と遊ぶ", "立花理香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (158, 12, 107901, 3, 48, "獣人族", 19, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "メルクリウス財団", "タマキ（サマー）", "AB", 0, "弱きを助け強きをくじく猫娘", 1, "猫とたわむれること", "沼倉愛美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (163, 12, 108001, 11, 49, "ヒューマン", 20, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "メルクリウス財団", "ミフユ（サマー）", "O", 0, "仕事も私事も効率優先な傭兵少女", 11, "傭兵などのアルバイト", "田所あずさ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (157, 7, 108101, 12, 42, "魔族", 18, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "悪魔偽王国軍（ディアボロス）", "シノブ（ハロウィン）", "AB", 0, "占いが得意な霊能少女", 22, "占い", "大坪由佳");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (130, 7, 108201, 1, 32, "魔族", 14, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "悪魔偽王国軍（ディアボロス）", "ミヤコ（ハロウィン）", "B", 0, "プリン大好きゴースト娘", 23, "プリンを食べること", "雨宮天");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (120, 14, 108301, 1, 22, "魔族", 11, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "ルーセント学院", "ミサキ（ハロウィン）", "A", 0, "ちょっとおませな恋に恋する女の子", 3, "ファッション誌鑑賞、コスメ集め", "久野美咲");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (163, 4, 108401, 6, 46, "ヒューマン", 17, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "カルミナ", "チカ（クリスマス）", "O", 0, "人々を守るために歌う、唱喚士の少女", 3, "各種楽器", "福原綾香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (150, 9, 108501, 6, 40, "ヒューマン", 12, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "サレンディア救護院", "クルミ（クリスマス）", "B", 0, "泣き虫で臆病な守ってあげたい女の子", 9, "観劇、おままごと", "植田佳奈");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (148, 9, 108601, 5, 38, "ヒューマン", 14, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "サレンディア救護院", "アヤネ（クリスマス）", "B", 0, "ぷうきちといつも一緒！", 10, "屋内でできる遊び", "芹澤優");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (155, 2, 108701, 8, 44, "獣人族", 16, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "トゥインクルウィッシュ", "ヒヨリ（ニューイヤー）", "A", 0, "人助けが大好き！　前向き格闘娘", 27, "人助け、応援", "東山奈央");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (158, 2, 108801, 4, 47, "ヒューマン", 17, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "トゥインクルウィッシュ", "ユイ（ニューイヤー）", "O", 0, "戦闘のサポートが得意な、心優しい少女", 5, "料理、人間観察", "種田梨沙");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (163, 2, 108901, 1, 46, "魔族", 18, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "トゥインクルウィッシュ", "レイ（ニューイヤー）", "B", 0, "クールで何事にも真っ直ぐな剣士", 12, "読書、乗馬、お茶", "早見沙織");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (154, 13, 109001, 7, 43, "魔族", 16, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "トワイライトキャラバン", "エリコ（バレンタイン）", "B", 0, "運命の相手に一途すぎる乙女", 30, "実験、裁縫、料理", "橋本ちなみ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (168, 3, 109101, 10, 54, "ヒューマン", 18, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "ラビリンス", "シズル（バレンタイン）", "O", 0, "お姉ちゃんがお世話してあげるからねっ！", 24, "家事全般", "生天目仁美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, "", 109201, 12, 55, "ヒューマン", 17, "私はアン！一応、マナリア王国の\n第一王女だけど…あまりかしこまらないで、\n気軽に仲良くしてくれたら嬉しいな！", "？？？", "アン", "AB", 0, "英霊と契約を結んだマナリアの天才王女", 1, "読書", "日笠陽子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (144, "", 109301, 2, 45, "ヒューマン", 16, "ルゥはルゥですぅ！マナリア魔法学院に\n通ってるですぅ。あなたもルゥの\nお友だちになってくれるですか？", "？？？", "ルゥ", "O", 0, "マナリア魔法学院の新入生", 4, "食べること、眠ること", "こやまきみこ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (167, "", 109401, 11, 67, "半人半竜", 17, "私はグレア。竜と人、両方の血を\n受け継いでいるの…\nえっと…よ、よろしくね", "？？？", "グレア", "B", 0, "人を超越した力を有す心優しい竜姫", 3, "ピアノ", "福原綾香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (157, 15, 109501, 11, 49, "ヒューマン", 18, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "ヴァイスフリューゲル　ランドソル支部", "クウカ（オーエド）", "AB", 0, "妄想大好き！　ほんとは照れ屋な女の子", 19, "小説を読むこと", "長妻樹里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (163, 15, 109601, 8, 51, "ヒューマン", 16, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "ヴァイスフリューゲル　ランドソル支部", "ニノン（オーエド）", "O", 0, "トーゴクの神秘、オシエテクダサイ！", 31, "忍法開発", "佐藤聡美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (154, "", 109701, 2, "??", "鬼族", 17, "", "？？？", "レム", "?", 0, "鬼がかりの万能妹メイド", 2, "演劇鑑賞、詩文", "水瀬いのり");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (154, "", 109801, 2, "??", "鬼族", 17, "", "？？？", "ラム", "?", 0, "毒舌系鬼姉メイド", 2, "読書", "村川梨衣");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (164, "", 109901, 9, "??", "ハーフエルフ", "??", "", "？？？", "エミリア", "?", 0, "銀髪のおっとりハーフエルフ", 23, "パックの毛繕い、勉強", "高橋李依");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (167, 14, 110001, 4, 48, "魔族", 17, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "ルーセント学院", "スズナ（サマー）", "O", 0, "天真爛漫で人気者のカリスマモデル", 10, "ファッション", "上坂すみれ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (162, 14, 110101, 8, 52, "魔族", 23, "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "ルーセント学院", "イオ（サマー）", "B", 0, "多くの男性を魅了する無垢な女教師", 14, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", "伊藤静");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (120, 14, 110201, 1, 22, "魔族", 11, "", "ルーセント学院", "ミサキ（サマー）", "A", 0, "ちょっとおませな恋に恋する女の子", 3, "ファッション誌鑑賞、コスメ集め", "久野美咲");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, 9, 110301, 10, 43, "エルフ", 17, "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "サレンディア救護院", "サレン（サマー）", "A", 0, "救護院を経営する優しい庶民派お嬢様", 4, "経営、お茶会", "堀江由衣");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (168, 10, 110401, 8, 54, "獣人族", 17, "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", "自警団（カォン）", "マコト（サマー）", "O", 0, "男勝りで情に厚いワイルド娘", 9, "お菓子作り", "小松未可子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (158, 10, 110501, 7, 53, "獣人族", 17, "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "自警団（カォン）", "カオリ（サマー）", "A", 0, "いつでも「なんくるないさ～」な天然娘", 7, "踊り、空手", "高森奈津美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (155, 10, 110601, 9, 42, "獣人族", 16, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "自警団（カォン）", "マホ（サマー）", "O", 0, "マホマホ王国のプリンセス", 22, "空想、ぬいぐるみ集め", "内田真礼");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (158, 6, 110701, 6, 44, "エルフ", 13, "", "フォレスティエ", "アオイ（編入生）", "AB", 0, "「友達」に憧れる、エルフの森の女の子", 6, "友達作りのイメトレ", "花澤香菜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (154, 16, 110801, 8, 42, "エルフ", 17, "", "聖テレサ女学院（なかよし部）", "クロエ", "O", 0, "ダウンタウン育ちのダウナー系エルフ", 7, "ダーツ", "種﨑敦美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, 16, 110901, 9, 46, "ヒューマン", 16, "", "聖テレサ女学院（なかよし部）", "チエル", "O", 0, "自由奔放ナチュラル無礼な現代っ子", 15, "ダンス、カラオケ", "佐倉綾音");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (142, 16, 111001, 2, 36, "ヒューマン", 18, "", "聖テレサ女学院（なかよし部）", "ユニ", "O", 0, "書庫に眠れる小さな賢人", 28, "読書", "小原好美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (118, 5, 111101, 2, 21, "エルフ", 8, "", "リトルリリカル", "キョウカ（ハロウィン）", "A", 0, "礼儀正しくしっかり者のちびっ子優等生", 2, "お勉強", "小倉唯");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (128, 5, 111201, 8, 27, "ヒューマン", 9, "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", "リトルリリカル", "ミソギ（ハロウィン）", "O", 0, "探検好きのイタズラっ子", 10, "いたずら、探検", "諸星すみれ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (117, 5, 111301, 4, 21, "獣人族", 10, "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", "リトルリリカル", "ミミ（ハロウィン）", "O", 0, "お歌もにんじんも、ウサギさんも大好き♪", 3, "かわいいもの集め", "日高里菜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (142, "", 111401, 1, 28, "ヒューマン", "??", "", "？？？", "ルナ", "?", 0, "おともだちを探す死霊術師の少女", 8, "「おともだち」を探すこと", "小倉唯");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (165, 8, 111501, 2, "??", "ヒューマン", 27, "", "王宮騎士団（NIGHTMARE）", "クリスティーナ（クリスマス）", "O", 0, "傍若無人な王宮騎士団副団長", 7, "強敵との闘争", "たかはし智秋");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (157, 4, 111601, 1, 40, "ヒューマン", 17, "", "カルミナ", "ノゾミ（クリスマス）", "B", 0, "歌って踊れる大人気アイドル", 24, "舞台鑑賞、ダンス", "日笠陽子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (172, 7, 111701, 5, 50, "魔族", "??", "", "悪魔偽王国軍（ディアボロス）", "イリヤ（クリスマス）", "A", 0, "かつては夜を支配した最強の吸血鬼", 5, "世界征服", "丹下桜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, 1, 111801, 3, 46, "ヒューマン", 17, "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "美食殿", "ぺコリーヌ（ニューイヤー）", "O", 0, "いつも元気な腹ペコ少女", 31, "食べ歩き、料理", "M・A・O");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (140, 1, 111901, 5, 35, "エルフ", 11, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "美食殿", "コッコロ（ニューイヤー）", "B", 0, "主を慕う、小さなガイド役", 11, "瞑想、動植物の飼育", "伊藤美来");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (152, 1, 112001, 9, 39, "獣人族", 14, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "美食殿", "キャル（ニューイヤー）", "A", 0, "行き倒れの謎のネコミミ魔法使い", 2, "猫と遊ぶ", "立花理香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (154, 9, 112101, 12, 43, "ヒューマン", 15, "うぅ…ごめんなさい～…\nまたキッチンを爆発させてしまいました～\nこれじゃあメイド失格です…", "サレンディア救護院", "スズメ（ニューイヤー）", "O", 0, "お嬢さまのためにがんばるドジっ娘メイド", 12, "ご奉仕", "悠木碧");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (152, 10, 112201, 11, 41, "獣人族", 15, "", "自警団（カォン）", "カスミ（マジカル）", "AB", 0, "頭脳明晰な美少女名探偵", 3, "読書、推理", "水瀬いのり");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (153, 11, 112301, 11, 40, "獣人族", 14, "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", "牧場（エリザベスパーク）", "シオリ（マジカル）", "A", 0, "読書が趣味の病弱少女", 3, "読書、お散歩", "小清水亜美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (159, 100, 112401, 4, 45, "ヒューマン", 17, "", "ニュージェネレーションズ", "ウヅキ（デレマス）", "O", 0, "弾ける笑顔！　アイドルを夢見る女の子", 24, "友達と長話", "大橋彩香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (165, 100, 112501, 8, 44, "ヒューマン", 15, "", "ニュージェネレーションズ", "リン（デレマス）", "B", 0, "クールビューティーな「蒼の剣士」", 10, "犬の散歩", "福原綾香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (161, 100, 112601, 12, 46, "ヒューマン", 15, "", "ニュージェネレーションズ", "ミオ（デレマス）", "B", 0, "スーパースターを目指す元気娘☆☆★", 1, "ショッピング", "原紗友里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (144, 11, 112701, 1, 42, "獣人族", 17, "", "牧場（エリザベスパーク）", "リン（レンジャー）", "B", 0, "遊びと睡眠が何より大事なぐうたら娘", 1, "あんパン", "小岩井ことり");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (142, 11, 112801, 3, 35, "ヒューマン", 20, "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", "牧場（エリザベスパーク）", "マヒル（レンジャー）", "B", 0, "みんなを笑顔にするお笑い牧場主", 3, "漫才", "新田恵海");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, 3, 112901, 8, 44, "ヒューマン", 15, "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "ラビリンス", "リノ（ワンダー）", "A", 0, "人懐っこくてマシンガントークな妹系少女", 25, "お裁縫", "阿澄佳奈");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (155, 15, 113001, 4, 43, "エルフ", 16, "", "ヴァイスフリューゲル　ランドソル支部", "アユミ（ワンダー）", "O", 0, "どこまでも一途に慕う、純情乙女", 7, "観察", "大関英里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (167, 13, 113101, 7, 54, "ヒューマン", 25, "", "トワイライトキャラバン", "ルカ（サマー）", "B", 0, "人情味溢れる粋でいなせな「姉御」", 11, "釣り", "佐藤利奈");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (159, 13, 113201, 7, 45, "魔族", 17, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "トワイライトキャラバン", "アンナ（サマー）", "A", 0, "前世を信じる中二病患者、「疾風の冥姫」", 5, "小説執筆", "髙野麻美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (166, 13, 113301, 8, 55, "魔族", 18, "", "トワイライトキャラバン", "ナナカ（サマー）", "O", 0, "オタク全開な魔法少女", 21, "読書、魔法", "佳村はるか");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, 6, 113401, 12, 46, "エルフ", 17, "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", "フォレスティエ", "ハツネ（サマー）", "A", 0, "みんなのために超能力を使う眠り姫", 24, "妹と遊ぶこと、二度寝、昼寝、早寝", "大橋彩香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (165, 6, 113501, 9, 54, "エルフ", 21, "", "フォレスティエ", "ミサト（サマー）", "O", 0, "母性溢れる優しいみんなの「ミサト先生」", 5, "絵本作り", "國府田マリ子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (171, 8, 113601, 10, 50, "ヒューマン", 25, "", "王宮騎士団（NIGHTMARE）", "ジュン（サマー）", "A", 0, "素顔を見せない冷静沈着な女性騎士", 25, "格闘技、湯浴み", "川澄綾子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (150, 7, 113701, 11, 42, "魔族", 13, "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "悪魔偽王国軍（ディアボロス）", "アカリ（エンジェル）", "O", 0, "甘え上手なみんなの人気者", 22, "サックス", "浅倉杏美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (150, 7, 113801, 11, 40, "魔族", 13, "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", "悪魔偽王国軍（ディアボロス）", "ヨリ（エンジェル）", "O", 0, "人見知りであまのじゃくな女の子", 22, "ゲーム全般", "原紗友里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (153, 4, 113901, 9, 45, "ヒューマン", 14, "", "カルミナ", "ツムギ（ハロウィン）", "AB", 0, "ファッション大好きなキュートガール", 7, "裁縫", "木戸衣吹");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (163, 2, 114001, 1, 46, "魔族", 18, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "トゥインクルウィッシュ", "レイ（ハロウィン）", "B", 0, "クールで何事にも真っ直ぐな剣士", 12, "読書、乗馬、お茶", "早見沙織");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (146, 8, 114101, 11, 40, "獣人族", 12, "", "王宮騎士団（NIGHTMARE）", "マツリ（ハロウィン）", "O", 0, "ヒーローに憧れる騎士見習いの少女", 25, "ヒーローごっこ", "下田麻美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (140, 15, 114201, 7, 33, "ヒューマン", 17, "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "ヴァイスフリューゲル　ランドソル支部", "モニカ（マジカル）", "A", 0, "見た目も中身もお子ちゃまな異国の軍人", 28, "お菓子屋通い", "辻あゆみ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (149, 8, 114301, 8, 43, "ヒューマン", 13, "", "王宮騎士団（NIGHTMARE）", "トモ（マジカル）", "A", 0, "義理堅くてからかい好きな剣術少女", 11, "剣術、年長者をからかう", "茅原実里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (157, 12, 114401, 3, 45, "ヒューマン", 18, "この私とともにいる限り、\nお金に不自由はさせませんわ！", "メルクリウス財団", "アキノ（クリスマス）", "AB", 0, "一人前の商人を目指すパワフルお嬢様", 12, "慈善事業", "松嵜麗");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, 9, 114501, 10, 43, "エルフ", 17, "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "サレンディア救護院", "サレン（クリスマス）", "A", 0, "救護院を経営する優しい庶民派お嬢様", 4, "経営、お茶会", "堀江由衣");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (164, 12, 114601, 3, 55, "エルフ", 22, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "メルクリウス財団", "ユカリ（クリスマス）", "A", 0, "純情でほっとけない大人の女性", 16, "ウインドーショッピング", "今井麻美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (148, "", 114701, 8, 40, "ヒューマン", 16, "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", "？？？", "ムイミ（ニューイヤー）", "O", 0, "さまよえる謎の少女", 11, "冒険、思い出話", "潘めぐみ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (149, "", 115001, 3, "??", "エルフ", 24, "", "？？？", "ネネカ（ニューイヤー）", "O", 0, "研究所に隠れ住む物静かなお姉さん", 24, "物真似、芸術鑑賞", "井口裕香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (140, 1, 115501, 5, 35, "エルフ", 11, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "美食殿", "コッコロ（儀装束）", "B", 0, "主を慕う、小さなガイド役", 11, "瞑想、動植物の飼育", "伊藤美来");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (158, 2, 115601, 4, 47, "ヒューマン", 17, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "トゥインクルウィッシュ", "ユイ（儀装束）", "O", 0, "戦闘のサポートが得意な、心優しい少女", 5, "料理、人間観察", "種田梨沙");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (152, 10, 115701, 11, 41, "獣人族", 15, "", "自警団（カォン）", "カスミ（サマー）", "AB", 0, "頭脳明晰な美少女名探偵", 3, "読書、推理", "水瀬いのり");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (150, 11, 115801, 3, 100, "獣人族", 17, "私、ごく普通の、どこにでもいる女の子よ！\nみ、見た目以外はね…", "牧場（エリザベスパーク）", "リマ（シンデレラ）", "A", 0, "乙女チックなもふもふアニマル", 14, "毛繕い、お喋り", "徳井青空");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (168, 10, 115901, 8, 54, "獣人族", 17, "腹へってたら言えよな\n簡単でよければ\nすっげー旨いもん食わせてやるよ！", "自警団（カォン）", "マコト（シンデレラ）", "O", 0, "男勝りで情に厚いワイルド娘", 9, "お菓子作り", "小松未可子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (155, 10, 116001, 9, 42, "獣人族", 16, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "自警団（カォン）", "マホ（シンデレラ）", "O", 0, "マホマホ王国のプリンセス", 22, "空想、ぬいぐるみ集め", "内田真礼");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (154, 16, 116201, 8, 42, "エルフ", 17, "", "聖テレサ女学院（なかよし部）", "クロエ（聖学祭）", "O", 0, "ダウンタウン育ちのダウナー系エルフ", 7, "ダーツ", "種﨑敦美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, 16, 116301, 9, 46, "ヒューマン", 16, "", "聖テレサ女学院（なかよし部）", "チエル（聖学祭）", "O", 0, "自由奔放ナチュラル無礼な現代っ子", 15, "ダンス、カラオケ", "佐倉綾音");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (142, 16, 116401, 2, 36, "ヒューマン", 18, "", "聖テレサ女学院（なかよし部）", "ユニ（聖学祭）", "O", 0, "書庫に眠れる小さな賢人", 28, "読書", "小原好美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (145, 17, 116501, 9, "???", "ドラゴン族", 13, "", "ドラゴンズネスト", "イノリ（タイムトラベル）", "AB", 0, "口が達者なヘタレドラゴン", 29, "ゲーム", "藤田茜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, 17, 116601, 6, "???", "ドラゴン族", 16, "", "ドラゴンズネスト", "カヤ（タイムトラベル）", "B", 0, "拳で語る喧嘩屋ドラゴン少女", 25, "格闘技", "小市眞琴");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (158, 6, 116701, 6, 44, "エルフ", 13, "", "フォレスティエ", "アオイ（作業服）", "AB", 0, "「友達」に憧れる、エルフの森の女の子", 6, "友達作りのイメトレ", "花澤香菜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (158, 12, 116801, 3, 48, "獣人族", 19, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "メルクリウス財団", "タマキ（作業服）", "AB", 0, "弱きを助け強きをくじく猫娘", 1, "猫とたわむれること", "沼倉愛美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (163, 12, 116901, 11, 49, "ヒューマン", 20, "私がキミの師匠になってあげる！\nもちろんタダとはいかないわ\n時給はしっかりもらうから", "メルクリウス財団", "ミフユ（作業服）", "O", 0, "仕事も私事も効率優先な傭兵少女", 11, "傭兵などのアルバイト", "田所あずさ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (154, 13, 117001, 7, 43, "魔族", 16, "『壊し屋』の二つ名を持つ私…\nですが、怖がる必要はありませんわ\nあなた様は大切な運命の人ですから…", "トワイライトキャラバン", "エリコ（サマー）", "B", 0, "運命の相手に一途すぎる乙女", 30, "実験、裁縫、料理", "橋本ちなみ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (168, 3, 117101, 10, 54, "ヒューマン", 18, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "ラビリンス", "シズル（サマー）", "O", 0, "お姉ちゃんがお世話してあげるからねっ！", 24, "家事全般", "生天目仁美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (157, 4, 117201, 1, 40, "ヒューマン", 17, "", "カルミナ", "ノゾミ（サマー）", "B", 0, "歌って踊れる大人気アイドル", 24, "舞台鑑賞、ダンス", "日笠陽子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (163, 4, 117301, 6, 46, "ヒューマン", 17, "私は人々の平和を守るため、唱喚術を使って\n戦います。…最近は、ア、アイドルとしても\n活動してますが、そちらはまだ不慣れで…", "カルミナ", "チカ（サマー）", "O", 0, "人々を守るために歌う、唱喚士の少女", 3, "各種楽器", "福原綾香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (153, 4, 117401, 9, 45, "ヒューマン", 14, "", "カルミナ", "ツムギ（サマー）", "AB", 0, "ファッション大好きなキュートガール", 7, "裁縫", "木戸衣吹");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (166, 13, 117501, 3, 53, "ヒューマン", 27, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "トワイライトキャラバン", "ミツキ（オーエド）", "A", 0, "実験が趣味の危険な科学者", 7, "研究、実験", "三石琴乃");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (150, 15, 117601, 10, 40, "エルフ", 14, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "ヴァイスフリューゲル　ランドソル支部", "ユキ（オーエド）", "AB", 0, "ボクは誰よりも美しい", 10, "鏡で自分を見ること", "大空直美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (158, 10, 117701, 7, 53, "獣人族", 17, "ハイターイ！　歌って踊って、\n最高に盛り上がるさ～！\nやさやさ、キミも一緒に踊るさ～！", "自警団（カォン）", "カオリ（ハロウィン）", "A", 0, "いつでも「なんくるないさ～」な天然娘", 7, "踊り、空手", "高森奈津美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (163, 15, 117801, 8, 51, "ヒューマン", 16, "スシ、ゲイシャ、テンプラ…\nはふぅ～！\nトーゴクの文化はステキデスね～！", "ヴァイスフリューゲル　ランドソル支部", "ニノン（ハロウィン）", "O", 0, "トーゴクの神秘、オシエテクダサイ！", 31, "忍法開発", "佐藤聡美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (167, 14, 117901, 4, 48, "魔族", 17, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "ルーセント学院", "スズナ（ハロウィン）", "O", 0, "天真爛漫で人気者のカリスマモデル", 10, "ファッション", "上坂すみれ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (160, 18, 118001, 9, 57, "ヒューマン", 26, "", "リッチモンド商工会", "クレジッタ", "A", 0, "忠義に目覚めた女商人", 19, "お金を数えること、悪だくみ", "Lynn");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (165, 19, 118101, 12, 53, "魔族", 20, "", "レイジ・レギオン", "ランファ", "O", 0, "静寂を求め歌う陰気少女", 28, "歌、読書、詩を書くこと", "原田彩楓");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (159, 19, 118201, 7, "??", "ヒューマン", 16, "", "レイジ・レギオン", "ミソラ", "A", 0, "明朗快活、なれど破滅に流るる溌溂少女", 2, "特に無し", "鬼頭明里");
