INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES ("???", "", 118601, "?", "???", "？？？", "??", "", "？？？", "ネビア", "?", 0, "幻霧に戯れる悪戯好きなガイド妖精", "?", "悪戯をすること", "相坂優歌");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (162, 14, 119001, 8, 52, "魔族", 23, "いつも助けてくれてありがとう\n私のほうが年上なのに\n頼ってばかりでごめんなさい～", "ルーセント学院", "イオ（ノワール）", "B", 0, "多くの男性を魅了する無垢な女教師", 14, "恋愛小説、恋愛舞台、恋愛漫画の鑑賞", "伊藤静");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (157, 15, 119101, 11, 49, "ヒューマン", 18, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "ヴァイスフリューゲル　ランドソル支部", "クウカ（ノワール）", "AB", 0, "妄想大好き！　ほんとは照れ屋な女の子", 19, "小説を読むこと", "長妻樹里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (142, 11, 119201, 3, 35, "ヒューマン", 20, "オラはどんな時でもみんなに笑顔を届ける\n最高の芸人目指してる！\n一緒に頑張るべ！", "牧場（エリザベスパーク）", "マヒル（クリスマス）", "B", 0, "みんなを笑顔にするお笑い牧場主", 3, "漫才", "新田恵海");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, 3, 119301, 8, 44, "ヒューマン", 15, "覚えていないと思うんですけど…\n私は妹なんですよ！\nだからお兄ちゃんって呼んでいいですか？", "ラビリンス", "リノ（クリスマス）", "A", 0, "人懐っこくてマシンガントークな妹系少女", 25, "お裁縫", "阿澄佳奈");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (130, 7, 119901, 1, 32, "魔族", 14, "難しいことはわからないの～\nただ毎日プリンを食べられるなら、\n幽霊のままでいいの～", "悪魔偽王国軍（ディアボロス）", "ミヤコ（クリスマス）", "B", 0, "プリン大好きゴースト娘", 23, "プリンを食べること", "雨宮天");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (168, 3, 120001, 10, 54, "ヒューマン", 18, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "ラビリンス", "シズル（ノワール）", "O", 0, "お姉ちゃんがお世話してあげるからねっ！", 24, "家事全般", "生天目仁美");
