INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, 1, 121001, 3, 46, "ヒューマン", 17, "", "美食殿", "ぺコリーヌ（オーバーロード）", "O", 0, "いつも元気な腹ペコ少女", 31, "食べ歩き、料理", "M・A・O");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (152, 1, 121101, 9, 39, "獣人族", 14, "", "美食殿", "キャル（オーバーロード）", "A", 0, "行き倒れの謎のネコミミ魔法使い", 2, "猫と遊ぶ", "立花理香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (160, 3, 121201, 7, "??", "ヒューマン", 25, "", "ラビリンス", "ラビリスタ（オーバーロード）", "AB", 0, "秘密結社ラビリンスの『迷宮女王』", 25, "人間観察", "沢城みゆき");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (150, 9, 121301, 6, 40, "ヒューマン", 12, "あの、えっと…私、く、クルミですぅ…\nふ、ふぇぇぇ…ど、どうしようぅ…\nは、恥かしくて…ご、ごめんなさいぃぃ！", "サレンディア救護院", "クルミ（ステージ）", "B", 0, "泣き虫で臆病な守ってあげたい女の子", 9, "観劇、おままごと", "植田佳奈");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (120, 14, 121401, 1, 22, "魔族", 11, "アタシのこと呼んだ？\nレディの魅力で夢中にさせてあげるわね！", "ルーセント学院", "ミサキ（ステージ）", "A", 0, "ちょっとおませな恋に恋する女の子", 3, "ファッション誌鑑賞、コスメ集め", "久野美咲");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (155, 15, 121501, 4, 43, "エルフ", 16, "", "ヴァイスフリューゲル　ランドソル支部", "アユミ（怪盗）", "O", 0, "どこまでも一途に慕う、純情乙女", 7, "観察", "大関英里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (145, 17, 121601, 9, "???", "ドラゴン族", 13, "", "ドラゴンズネスト", "イノリ（怪盗）", "AB", 0, "口が達者なヘタレドラゴン", 29, "ゲーム", "藤田茜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (159, 13, 121901, 7, 45, "魔族", 17, "いいか、絶対に私を真名で呼ぶなよ？\n常に「機関」の眼や耳の存在を疑え\nそれが、生きのびるための術だ…！", "トワイライトキャラバン", "アンナ（パイレーツ）", "A", 0, "前世を信じる中二病患者、「疾風の冥姫」", 5, "小説執筆", "髙野麻美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (157, 7, 122001, 12, 42, "魔族", 18, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "悪魔偽王国軍（ディアボロス）", "シノブ（パイレーツ）", "AB", 0, "占いが得意な霊能少女", 22, "占い", "大坪由佳");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (158, 6, 122101, 6, 44, "エルフ", 13, "", "フォレスティエ", "アオイ（キャンプ）", "AB", 0, "「友達」に憧れる、エルフの森の女の子", 6, "友達作りのイメトレ", "花澤香菜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (164, 12, 122201, 3, 55, "エルフ", 22, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "メルクリウス財団", "ユカリ（キャンプ）", "A", 0, "純情でほっとけない大人の女性", 16, "ウインドーショッピング", "今井麻美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (149, "", 122301, 12, 41, "魔族", "??", "", "？？？", "ヴァンピィ", "AB", 0, "けんぞくのご主人様", 6, "お散歩、お料理", "釘宮理恵");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (155, 2, 122401, 8, 44, "獣人族", 16, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "トゥインクルウィッシュ", "ヒヨリ（サマー）", "A", 0, "人助けが大好き！　前向き格闘娘", 27, "人助け、応援", "東山奈央");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (163, 2, 122501, 1, 46, "魔族", 18, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "トゥインクルウィッシュ", "レイ（サマー）", "B", 0, "クールで何事にも真っ直ぐな剣士", 12, "読書、乗馬、お茶", "早見沙織");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (158, 2, 122601, 4, 47, "ヒューマン", 17, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "トゥインクルウィッシュ", "ユイ（サマー）", "O", 0, "戦闘のサポートが得意な、心優しい少女", 5, "料理、人間観察", "種田梨沙");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (118, 5, 122701, 2, 21, "エルフ", 8, "", "リトルリリカル", "キョウカ（サマー）", "A", 0, "礼儀正しくしっかり者のちびっ子優等生", 2, "お勉強", "小倉唯");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (128, 5, 122801, 8, 27, "ヒューマン", 9, "イタズラなら任せて！\nにいちゃん、引っかからないように気を付けなよー♪", "リトルリリカル", "ミソギ（サマー）", "O", 0, "探検好きのイタズラっ子", 10, "いたずら、探検", "諸星すみれ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (117, 5, 122901, 4, 21, "獣人族", 10, "ぴょんぴょん、うさぎさんになりたいな～♪　\nミミ、うさぎさんになれたら、\n最初におにいちゃんに見せてあげるね！", "リトルリリカル", "ミミ（サマー）", "O", 0, "お歌もにんじんも、ウサギさんも大好き♪", 3, "かわいいもの集め", "日高里菜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (150, "", 123001, "?", "???", "？？？", "??", "", "？？？", "アメス", "?", 0, "新たな姿で騎士の冒険を支え続ける妖精", "?", "？？？", "相坂優歌");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (155, 10, 123101, 9, 42, "獣人族", 16, "マホマホ王国のお姫はんの、マホ姫どす！\nけったいな顔してどないしはったん？\nマホマホ王国はずーっと遠くの国なんどす？", "自警団（カォン）", "マホ（エクスプローラー）", "O", 0, "マホマホ王国のプリンセス", 22, "空想、ぬいぐるみ集め", "内田真礼");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (148, 9, 123201, 5, 38, "ヒューマン", 14, "この子はね、ぷうきちって言うんだ\n武器なんだけど、しゃべるんだよ♪\n大事な大事な、私の友達なんだぁ～！", "サレンディア救護院", "アヤネ（エクスプローラー）", "B", 0, "ぷうきちといつも一緒！", 10, "屋内でできる遊び", "芹澤優");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (157, 19, 123301, 6, 55, "魔族？", 19, "", "レイジ・レギオン", "ネア", "B", 0, "ショタ大好き♪　ギャル系スライム娘", 13, "可愛いショタと遊ぶ、買い物", "和氣あず未");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (171, 8, 123401, 10, 50, "ヒューマン", 25, "", "王宮騎士団（NIGHTMARE）", "ジュン（キャンプ）", "A", 0, "素顔を見せない冷静沈着な女性騎士", 25, "格闘技、湯浴み", "川澄綾子");
