INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (149, 8, 123601, 8, 43, "ヒューマン", 13, "", "王宮騎士団（NIGHTMARE）", "トモ（ハロウィン）", "A", 0, "義理堅くてからかい好きな剣術少女", 11, "剣術、年長者をからかう", "茅原実里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (166, 13, 123701, 8, 55, "魔族", 18, "", "トワイライトキャラバン", "ナナカ（ハロウィン）", "O", 0, "オタク全開な魔法少女", 21, "読書、魔法", "佳村はるか");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (165, 8, 123801, 2, "??", "ヒューマン", 27, "", "王宮騎士団（NIGHTMARE）", "クリスティーナ（ワイルド）", "O", 0, "傍若無人な王宮騎士団副団長", 7, "強敵との闘争", "たかはし智秋");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (146, 8, 123901, 11, 40, "獣人族", 12, "", "王宮騎士団（NIGHTMARE）", "マツリ（ワイルド）", "O", 0, "ヒーローに憧れる騎士見習いの少女", 25, "ヒーローごっこ", "下田麻美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (150, 7, 124001, 11, 42, "魔族", 13, "アカリ、まだわからないことが多くて…\nだからこれから\nいろいろ教えてくださいね、お兄ちゃん！", "悪魔偽王国軍（ディアボロス）", "アカリ（クリスマス）", "O", 0, "甘え上手なみんなの人気者", 22, "サックス", "浅倉杏美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (150, 7, 124101, 11, 40, "魔族", 13, "え、えっと…こ、こういうときって、\nどういうことを言えばいいんだっけ…\nうう、どうしてちゃんと喋れないの…", "悪魔偽王国軍（ディアボロス）", "ヨリ（クリスマス）", "O", 0, "人見知りであまのじゃくな女の子", 22, "ゲーム全般", "原紗友里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (171, 8, 124201, 10, 50, "ヒューマン", 25, "", "王宮騎士団（NIGHTMARE）", "ジュン（クリスマス）", "A", 0, "素顔を見せない冷静沈着な女性騎士", 25, "格闘技、湯浴み", "川澄綾子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (168, 17, 124501, 4, "???", "ドラゴン族", 25, "", "ドラゴンズネスト", "ホマレ（ニューイヤー）", "O", 0, "妖しい微笑で全てを見透かす臥竜の頭領", 17, "絵画、読書", "大西沙織");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (165, 6, 124601, 9, 54, "エルフ", 21, "", "フォレスティエ", "ミサト（ニューイヤー）", "O", 0, "母性溢れる優しいみんなの「ミサト先生」", 5, "絵本作り", "國府田マリ子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (166, 13, 124701, 3, 53, "ヒューマン", 27, "私は科学者だけど、\n医者の真似事もしてるの\n病気になったら診てあげるわ", "トワイライトキャラバン", "ミツキ（ニューイヤー）", "A", 0, "実験が趣味の危険な科学者", 7, "研究、実験", "三石琴乃");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (157, 4, 124801, 1, 40, "ヒューマン", 17, "", "カルミナ", "ノゾミ（リベレイター）", "B", 0, "歌って踊れる大人気アイドル", 24, "舞台鑑賞、ダンス", "日笠陽子");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, 17, 124901, 6, "???", "ドラゴン族", 16, "", "ドラゴンズネスト", "カヤ（リベレイター）", "B", 0, "拳で語る喧嘩屋ドラゴン少女", 25, "格闘技", "小市眞琴");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (148, "", 125001, 8, 40, "ヒューマン", 16, "いいんだ、アタシは……独りでも。大丈夫だから、もう慣れたからさぁ", "？？？", "ムイミ（リベレイター）", "O", 0, "さまよえる謎の少女", 11, "冒険、思い出話", "潘めぐみ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (158, 12, 125101, 3, 48, "獣人族", 19, "お金もうけの話なら、ぜひともあたしに\n持ってくるにゃ！　稼げるなら１ルピだって\n見逃さないのが、あたしの信条にゃ～♪", "メルクリウス財団", "タマキ（カフェ）", "AB", 0, "弱きを助け強きをくじく猫娘", 1, "猫とたわむれること", "沼倉愛美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (140, 15, 125201, 7, 33, "ヒューマン", 17, "「白き翼」こと、ヴァイスフリューゲル…\nその名に恥じぬよう、天高く舞い、\n華麗に敵を倒してみせる！", "ヴァイスフリューゲル　ランドソル支部", "モニカ（カフェ）", "A", 0, "見た目も中身もお子ちゃまな異国の軍人", 28, "お菓子屋通い", "辻あゆみ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (140, 1, 125301, 5, 35, "エルフ", 11, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "美食殿", "コッコロ（レンジャー）", "B", 0, "主を慕う、小さなガイド役", 11, "瞑想、動植物の飼育", "伊藤美来");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (153, 11, 125401, 11, 40, "獣人族", 14, "ゴホッ、ゴホッ…か、身体は弱いけど、\nせめて気持ちだけでも前向きに…！\nあっ、でもダメ…立ちくらみが…", "牧場（エリザベスパーク）", "シオリ（レンジャー）", "A", 0, "読書が趣味の病弱少女", 3, "読書、お散歩", "小清水亜美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, "", 125501, 3, 45, "ヒューマン", 17, "", "？？？", "ジータ（ウォーロック）", "O", 0, "空への冒険を夢見る騎空士の少女", 10, "冒険、おしゃべり", "金元寿子");
