INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (152, "", 125701, 9, 43, "ヒューマン", 24, "", "？？？", "カリン（アルケミスト）", "A", 0, "【ギルド管理協会】職員の親切なお姉さん", 12, "書類仕事、散歩、ボードゲーム", "洲崎綾");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (154, 20, 125801, 4, 44, "ヒューマン", 15, "", "アルターメイデン", "リリ（フォールン）", "A", 0, "贖罪を胸に強さを求める妹系大和撫子", 29, "華道、読書（古典）、トーゴク画", "鈴木みのり");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (147, 20, 126001, 11, 42, "ヒューマン", 13, "", "アルターメイデン", "クリア（フォールン）", "O", 0, "忘れ難い罪過を抱える、黒き翼の聖女", 1, "お菓子作り、花の世話、バイオリン演奏", "前田佳織里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (135, 20, 126101, 3, 34, "獣人族", 10, "", "アルターメイデン", "プレシア（フォールン）", "O", 0, "正義の魂を受け継ぐ、爆食系天然天才娘", 1, "ごはんをたべること", "高尾奏音");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (172, 7, 126201, 5, 50, "魔族", "??", "", "悪魔偽王国軍（ディアボロス）", "イリヤ（儀装束）", "A", 0, "かつては夜を支配した最強の吸血鬼", 5, "世界征服", "丹下桜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (150, 15, 126301, 10, 40, "エルフ", 14, "ボクって本当に美しいなあ…\n可愛くて美しいなんて本当に罪だと思うけど\n生まれもったものだから仕方ないんだ♪", "ヴァイスフリューゲル　ランドソル支部", "ユキ（儀装束）", "AB", 0, "ボクは誰よりも美しい", 10, "鏡で自分を見ること", "大空直美");
