INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (149, "", 126601, 3, "??", "エルフ", 24, "", "？？？", "ネネカ（サマー）", "O", 0, "研究所に隠れ住む物静かなお姉さん", 24, "物真似、芸術鑑賞", "井口裕香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (157, 12, 126701, 3, 45, "ヒューマン", 18, "この私とともにいる限り、\nお金に不自由はさせませんわ！", "メルクリウス財団", "アキノ（サマー）", "AB", 0, "一人前の商人を目指すパワフルお嬢様", 12, "慈善事業", "松嵜麗");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (164, 12, 126801, 3, 55, "エルフ", 22, "キミには情けないところばかり\n見られているけど、こんなところ、\nキミ以外には見せないんだからね？", "メルクリウス財団", "ユカリ（サマー）", "A", 0, "純情でほっとけない大人の女性", 16, "ウインドーショッピング", "今井麻美");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (165, 19, 126901, 12, 53, "魔族", 20, "", "レイジ・レギオン", "ランファ（サマー）", "O", 0, "静寂を求め歌う陰気少女", 28, "歌、読書、詩を書くこと", "原田彩楓");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (157, 15, 127001, 11, 49, "ヒューマン", 18, "あなたのことを考えていました\n…逆らえないクウカをああして、こうして\nぐふ、ぐふふふ…", "ヴァイスフリューゲル　ランドソル支部", "クウカ（サマー）", "AB", 0, "妄想大好き！　ほんとは照れ屋な女の子", 19, "小説を読むこと", "長妻樹里");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (157, 7, 127101, 12, 42, "魔族", 18, "私、小さい頃から人には見えないものが\n見えていたんです。今もあなたの後ろに\n一人、二人、三人…賑やかですね", "悪魔偽王国軍（ディアボロス）", "シノブ（サマー）", "AB", 0, "占いが得意な霊能少女", 22, "占い", "大坪由佳");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (152, 1, 127201, 9, 39, "獣人族", 14, "なに、モタモタしてんのよ\n仕方ないから、あたしが手伝ってあげるわ\nいい？　感謝しなさいよね！", "美食殿", "キャル（編入生）", "A", 0, "行き倒れの謎のネコミミ魔法使い", 2, "猫と遊ぶ", "立花理香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (167, 14, 127301, 4, 48, "魔族", 17, "ヒデサイ、ちょっす～！　うち、漢字と計算は\nちょっち…てか、おに苦手なんだ～\nでもでも、ファッションだったら任せて～！", "ルーセント学院", "スズナ（編入生）", "O", 0, "天真爛漫で人気者のカリスマモデル", 10, "ファッション", "上坂すみれ");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, 9, 127501, 10, 43, "エルフ", 17, "貧乏性？　いいえ、\n「もったいない」の精神で\n日々を過ごしてるだけよ！", "サレンディア救護院", "サレン（サラサリア）", "A", 0, "救護院を経営する優しい庶民派お嬢様", 4, "経営、お茶会", "堀江由衣");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (167, 13, 127601, 7, 54, "ヒューマン", 25, "", "トワイライトキャラバン", "ルカ（サラサリア）", "B", 0, "人情味溢れる粋でいなせな「姉御」", 11, "釣り", "佐藤利奈");
