INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, 1, 127901, 3, 46, "ヒューマン", 17, "あ、あの…何か食べ物持っていませんか？\nもう、お腹ペコペコで…", "美食殿", "ペコリーヌ（クリスマス）", "O", 0, "いつも元気な腹ペコ少女", 31, "食べ歩き、料理", "M・A・O");
