INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (145, 17, 128301, 9, "???", "ドラゴン族", 13, "", "ドラゴンズネスト", "イノリ（ニューイヤー）", "AB", 0, "口が達者なヘタレドラゴン", 29, "ゲーム", "藤田茜");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (156, 6, 128401, 12, 46, "エルフ", 17, "私はハツネ！　困っている人の味方だよ！\n困った時は、いつでも言ってね♪\n私のちょ…ま、魔法で助けてあげるから！", "フォレスティエ", "ハツネ（ニューイヤー）", "A", 0, "みんなのために超能力を使う眠り姫", 24, "妹と遊ぶこと、二度寝、昼寝、早寝", "大橋彩香");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (152, 10, 128501, 11, 41, "獣人族", 15, "", "自警団（カォン）", "カスミ（ニューイヤー）", "AB", 0, "頭脳明晰な美少女名探偵", 3, "読書、推理", "水瀬いのり");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (155, 2, 128701, 8, 44, "獣人族", 16, "こんにちは！　ヒヨリでっす！\n困っている人がいたら助けにいくよ！\nよかったら一緒に来ない？", "トゥインクルウィッシュ", "ヒヨリ（アストラル）", "A", 0, "人助けが大好き！　前向き格闘娘", 27, "人助け、応援", "東山奈央");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (163, 2, 128801, 1, 46, "魔族", 18, "キミと会ったのもきっと何かの縁だ\n一緒に塔の頂上を目指す仲間として\n頑張っていこう。よろしく頼む", "トゥインクルウィッシュ", "レイ（アストラル）", "B", 0, "クールで何事にも真っ直ぐな剣士", 12, "読書、乗馬、お茶", "早見沙織");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (158, 2, 128901, 4, 47, "ヒューマン", 17, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "トゥインクルウィッシュ", "ユイ（アストラル）", "O", 0, "戦闘のサポートが得意な、心優しい少女", 5, "料理、人間観察", "種田梨沙");
