INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (158, 2, 136401, 4, 47, "ヒューマン", 17, "あんまり役に立てるかはわからないけど…\nわたしも頑張って、\nみんなをサポートするね！", "トゥインクルウィッシュ", "ユイ（クリスマス）", "O", 0, "戦闘のサポートが得意な、心優しい少女", 5, "料理、人間観察", "種田梨沙");
INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (168, 3, 136501, 10, 54, "ヒューマン", 18, "身の回りのお世話はお姉ちゃんがやってあげるね！\nお料理も、お洗濯も、お掃除も\nお風呂で背中も流してあげちゃうぞっ！", "ラビリンス", "シズル（ニューイヤー）", "O", 0, "お姉ちゃんがお世話してあげるからねっ！", 24, "家事全般", "生天目仁美");
