INSERT INTO `v1_8e4f84837e0cb36480b43c8fd1fd2581609247fdcb5070bfebf2517610c2ff95` VALUES (164, 1, 137601, 5, 48, "エルフ", 11, "主さまのガイド役を仰せつかりました\nわたくし、主さまに満足していただけるよう\n誠心誠意尽くさせていただきます", "美食殿", "コッコロ（嚮導幼君）", "B", 0, "主を想い、“進化”したガイド役", 11, "瞑想、動植物の飼育", "伊藤美来");
